# The vertex connectivity function has a bug - let me fix it
# Actually the issue is with the source/sink handling. Let me rewrite properly.

def vertex_connectivity_correct(edges, n):
    """Compute vertex connectivity correctly."""
    from collections import deque

    # Build adjacency
    adj = [[False]*n for _ in range(n)]
    for u,v in edges:
        adj[u][v] = True
        adj[v][u] = True

    def max_flow_node_split(s, t):
        # 2n nodes: i_in = i, i_out = i+n
        N = 2*n
        # capacity matrix
        cap = [[0]*N for _ in range(N)]

        for i in range(n):
            if i == s or i == t:
                cap[i][i+n] = n+1  # effectively infinite
            else:
                cap[i][i+n] = 1

        for u in range(n):
            for v in range(n):
                if adj[u][v]:
                    cap[u+n][v] = n+1  # effectively infinite

        source = s+n  # s_out
        sink = t      # t_in

        total_flow = 0
        while True:
            # BFS to find augmenting path
            parent = [-1]*N
            visited = [False]*N
            visited[source] = True
            queue = deque([source])
            found = False
            while queue and not found:
                u = queue.popleft()
                for v in range(N):
                    if not visited[v] and cap[u][v] > 0:
                        visited[v] = True
                        parent[v] = u
                        if v == sink:
                            found = True
                            break
                        queue.append(v)
            if not found:
                break
            # Find min capacity along path
            path_flow = float('inf')
            v = sink
            while v != source:
                u = parent[v]
                path_flow = min(path_flow, cap[u][v])
                v = u
            # Update capacities
            v = sink
            while v != source:
                u = parent[v]
                cap[u][v] -= path_flow
                cap[v][u] += path_flow
                v = u
            total_flow += path_flow
        return total_flow

    # Vertex connectivity = min over all pairs (s,t) not adjacent... 
    # Actually min over ALL pairs s != t
    min_vc = float('inf')
    for s in range(n):
        for t in range(n):
            if s != t:
                f = max_flow_node_split(s, t)
                min_vc = min(min_vc, f)
    return min_vc

def max_independent_set_size(edges, n):
    """Find maximum independent set size."""
    adj = [[False]*n for _ in range(n)]
    for u,v in edges:
        adj[u][v] = True
        adj[v][u] = True

    max_is = 0
    for size in range(n, 0, -1):
        if size <= max_is:
            break
        for subset in combinations(range(n), size):
            independent = True
            for i, j in combinations(subset, 2):
                if adj[i][j]:
                    independent = False
                    break
            if independent:
                if size > max_is:
                    max_is = size
                break
        if max_is >= size:
            break
    return max_is

