        adj[v][u] = True
    def max_flow_node_split(s, t):
        N = 2*n
        cap = [[0]*N for _ in range(N)]
        for i in range(n):
            cap[i][i+n] = n+1 if (i == s or i == t) else 1
        for u in range(n):
            for v in range(n):
                if adj[u][v]:
                    cap[u+n][v] = n+1
        source, sink = s+n, t
        total_flow = 0
        while True:
            parent = [-1]*N
            visited = [False]*N
            visited[source] = True
            queue = deque([source])
            found = False
            while queue and not found:
                u = queue.popleft()
                for v in range(N):
                    if not visited[v] and cap[u][v] > 0:
                        visited[v] = True
                        parent[v] = u
                        if v == sink: found = True; break
                        queue.append(v)
            if not found: break
            path_flow = float('inf')
            v = sink
            while v != source:
                u = parent[v]; path_flow = min(path_flow, cap[u][v]); v = u
            v = sink
            while v != source:
                u = parent[v]; cap[u][v] -= path_flow; cap[v][u] += path_flow; v = u
            total_flow += path_flow
        return total_flow
    min_vc = float('inf')
    for s in range(n):
        for t in range(n):
            if s != t:
                min_vc = min(min_vc, max_flow_node_split(s, t))
    return min_vc

